// Fixed original auth consumers + actual protobuf roundtrip, no ParticipantImpl,
// no fabricated Go WS/TrackPublished success. Public WS is a separate gate.
package main
import("encoding/json";"os";"strings";"github.com/livekit/protocol/auth";pb "github.com/livekit/protocol/livekit";"google.golang.org/protobuf/proto")
type input struct{ID string `json:"id"`;Sources []string `json:"sources"`;Source int32 `json:"source"`;CanPublish *bool `json:"can_publish"`}
func main(){f,e:=os.Open(os.Args[1]);if e!=nil{panic(e)};var cases []input;if e=json.NewDecoder(f).Decode(&cases);e!=nil{panic(e)};if e=f.Close();e!=nil{panic(e)};if len(cases)!=12{panic("complete12")};seen:=map[string]bool{};for _,c:=range cases{if c.ID==""||seen[c.ID]{panic("unique12")};seen[c.ID]=true;grant:=auth.VideoGrant{CanPublish:c.CanPublish,CanPublishSources:c.Sources};request:=&pb.SignalRequest{Message:&pb.SignalRequest_AddTrack{AddTrack:&pb.AddTrackRequest{Cid:"actual-wire",Type:pb.TrackType_VIDEO,Source:pb.TrackSource(c.Source)}}};wire,e:=proto.Marshal(request);if e!=nil{panic(e)};var decoded pb.SignalRequest;if e=proto.Unmarshal(wire,&decoded);e!=nil{panic(e)};source:=decoded.GetAddTrack().GetSource();allowed:=grant.GetCanPublishSource(source);var published any;if allowed{info:=&pb.TrackInfo{Source:source};wire,e=proto.Marshal(info);if e!=nil{panic(e)};var again pb.TrackInfo;if e=proto.Unmarshal(wire,&again);e!=nil{panic(e)};published=int32(again.Source)};permission:=grant.ToPermission();projection:=[]int32{};for _,v:=range permission.CanPublishSources{projection=append(projection,int32(v))};incoming:=proto.Clone(permission).(*pb.ParticipantPermission);incoming.CanPublishSources=[]pb.TrackSource{source};admin:=grant.Clone();matches:=admin.MatchesPermission(incoming);if !matches{admin.UpdateFromPermission(incoming)};after:=[]int32{};for _,v:=range admin.ToPermission().CanPublishSources{after=append(after,int32(v))};rawSources:=append([]string{},admin.CanPublishSources...);row:=map[string]any{"api_matches":matches,"api_raw_sources":rawSources,"api_permission_sources":after,"api_allowed":admin.GetCanPublishSource(source),"api_repeated_matches":admin.MatchesPermission(incoming),"id":c.ID,"request_source":int32(source),"canonical_source":strings.ToLower(source.String()),"allowed":allowed,"track_source":published,"permission_sources":projection,"scope":"original GetCanPublishSource/ToPermission/enum.String + actual SignalRequest/TrackInfo protobuf roundtrip; not participant/WS/media"};if e=json.NewEncoder(os.Stdout).Encode(row);e!=nil{panic(e)}}}
